def parse_color(s):
    s = s.strip()
    if s.lower() in COLOR_NAMES:
        s = COLOR_NAMES[s.lower()]

    if s.startswith('#'):
        s = s[1:]
        if len(s) == 3:
            return (int(s[0]*2, 16)/255.0, int(s[1]*2, 16)/255.0, int(s[2]*2, 16)/255.0)
        elif len(s) == 6:
            return (int(s[0:2], 16)/255.0, int(s[2:4], 16)/255.0, int(s[4:6], 16)/255.0)

    m = re.match(r'rgb\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\)', s)
    if m:
        return (int(m.group(1))/255.0, int(m.group(2))/255.0, int(m.group(3))/255.0)

    m = re.match(r'hsl\(\s*([\d.]+)\s*,\s*([\d.]+)%\s*,\s*([\d.]+)%\s*\)', s)
    if m:
        h, s_val, l = float(m.group(1)), float(m.group(2))/100.0, float(m.group(3))/100.0
        r, g, b = colorsys.hls_to_rgb(h/360.0, l, s_val)
        return (r, g, b)

    try:
        if len(s) == 6:
            return (int(s[0:2], 16)/255.0, int(s[2:4], 16)/255.0, int(s[4:6], 16)/255.0)
    except:
        pass

    raise ValueError(f"Unknown color format: {s}")

def rgb_to_hsl(r, g, b):
    h, l, s = colorsys.rgb_to_hls(r, g, b)
    return (h*360.0, s, l)

def hsl_to_rgb(h, s, l):
    r, g, b = colorsys.hls_to_rgb(h/360.0, l, s)
    return (r, g, b)

def pivot_rgb(n):
    return (n / 12.92) if n <= 0.04045 else ((n + 0.055) / 1.055) ** 2.4

def pivot_xyz(n):
    return n ** (1.0 / 3.0) if n > 0.008856 else (7.787 * n) + (16.0 / 116.0)

def rgb_to_xyz(r, g, b):
    r = pivot_rgb(r)
    g = pivot_rgb(g)
    b = pivot_rgb(b)
    x = r * 0.4124 + g * 0.3576 + b * 0.1805
    y = r * 0.2126 + g * 0.7152 + b * 0.0722
    z = r * 0.0193 + g * 0.1192 + b * 0.9505
    return (x, y, z)

def xyz_to_lab(x, y, z):
    x = pivot_xyz(x / 0.95047)
    y = pivot_xyz(y / 1.00000)
    z = pivot_xyz(z / 1.08883)
    l = max(0.0, (116.0 * y) - 16.0)
    a = 500.0 * (x - y)
    b = 200.0 * (y - z)
    return (l, a, b)

def rgb_to_lab(r, g, b):
    x, y, z = rgb_to_xyz(r, g, b)
    return xyz_to_lab(x, y, z)

def pivot_lab(n):
    n3 = n ** 3.0
    return n3 if n3 > 0.008856 else (n - 16.0 / 116.0) / 7.787

def pivot_xyz_to_rgb(n):
    return 12.92 * n if n <= 0.0031308 else 1.055 * (n ** (1.0 / 2.4)) - 0.055

def lab_to_xyz(l, a, b):
    y = (l + 16.0) / 116.0
    x = a / 500.0 + y
    z = y - b / 200.0
    x = 0.95047 * pivot_lab(x)
    y = 1.00000 * pivot_lab(y)
    z = 1.08883 * pivot_lab(z)
    return (x, y, z)

def xyz_to_rgb(x, y, z):
    r = x *  3.2406 + y * -1.5372 + z * -0.4986
    g = x * -0.9689 + y *  1.8758 + z *  0.0415
    b = x *  0.0557 + y * -0.2040 + z *  1.0570
    r = clamp(pivot_xyz_to_rgb(r))
    g = clamp(pivot_xyz_to_rgb(g))
    b = clamp(pivot_xyz_to_rgb(b))
    return (r, g, b)

def lab_to_rgb(l, a, b):
    x, y, z = lab_to_xyz(l, a, b)
    return xyz_to_rgb(x, y, z)

def get_colors(args_colors):
    colors = []
    if args_colors:
        for c in args_colors:
            if c == '-':
                for line in sys.stdin:
                    colors.append(parse_color(line.strip()))
            else:
                colors.append(parse_color(c))
    else:
        if not sys.stdin.isatty():
            for line in sys.stdin:
                line = line.strip()
                if line:
                    colors.append(parse_color(line))
    return colors

def format_color(fmt, r, g, b):
    if fmt == 'hex':
        return f"#{int(r*255):02x}{int(g*255):02x}{int(b*255):02x}"
    elif fmt == 'rgb':
        return f"rgb({int(r*255)}, {int(g*255)}, {int(b*255)})"
    elif fmt == 'hsl':
        h, s, l = rgb_to_hsl(r, g, b)
        return f"hsl({int(h)}, {s*100:.1f}%, {l*100:.1f}%)"
    elif fmt == 'lab':
        l, a, bb = rgb_to_lab(r, g, b)
        return f"Lab({int(l)}, {int(a)}, {int(bb)})"
    elif fmt == 'name':
        min_dist = float('inf')
        best_name = "black"
        for name, hex_val in COLOR_NAMES.items():
            if name == "transparent": continue
            nr, ng, nb = parse_color(hex_val)
            dist = (r-nr)**2 + (g-ng)**2 + (b-nb)**2
            if dist < min_dist:
                min_dist = dist
                best_name = name
        return best_name
    return f"#{int(r*255):02x}{int(g*255):02x}{int(b*255):02x}"

def mix_colors(c1, c2, fraction=0.5):
    l1, a1, b1 = rgb_to_lab(*c1)
    l2, a2, b2 = rgb_to_lab(*c2)
    l = l1 * (1 - fraction) + l2 * fraction
    a = a1 * (1 - fraction) + a2 * fraction
    bb = b1 * (1 - fraction) + b2 * fraction
    return lab_to_rgb(l, a, bb)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('-m', '--color-mode')
    parser.add_argument('--color-picker')
    subparsers = parser.add_subparsers(dest='command')

    p_color = subparsers.add_parser('color')
    p_color.add_argument('color', nargs='*')

    p_format = subparsers.add_parser('format')
    p_format.add_argument('type', nargs='?', default='hex')
    p_format.add_argument('color', nargs='*')

    p_mix = subparsers.add_parser('mix')
    p_mix.add_argument('-f', '--fraction', type=float, default=0.5)
