    p_mix.add_argument('base_color')
    p_mix.add_argument('color', nargs='*')

    p_lighten = subparsers.add_parser('lighten')
    p_lighten.add_argument('amount', type=float)
    p_lighten.add_argument('color', nargs='*')

    p_darken = subparsers.add_parser('darken')
    p_darken.add_argument('amount', type=float)
    p_darken.add_argument('color', nargs='*')

    p_saturate = subparsers.add_parser('saturate')
    p_saturate.add_argument('amount', type=float)
    p_saturate.add_argument('color', nargs='*')

    p_desat = subparsers.add_parser('desaturate')
    p_desat.add_argument('amount', type=float)
    p_desat.add_argument('color', nargs='*')

    p_comp = subparsers.add_parser('complement')
    p_comp.add_argument('color', nargs='*')

    p_rot = subparsers.add_parser('rotate')
    p_rot.add_argument('degrees', type=float)
    p_rot.add_argument('color', nargs='*')

    p_to_gray = subparsers.add_parser('to-gray')
    p_to_gray.add_argument('color', nargs='*')

    p_gray = subparsers.add_parser('gray')
    p_gray.add_argument('lightness', type=float)

    p_text = subparsers.add_parser('textcolor')
    p_text.add_argument('color', nargs='*')

    p_dist = subparsers.add_parser('distinct')
    p_dist.add_argument('count', type=int)

    p_rand = subparsers.add_parser('random')
    p_rand.add_argument('-n', '--number', type=int, default=10)
    p_rand.add_argument('-s', '--strategy', default='vivid')

    p_list = subparsers.add_parser('list')

    p_check = subparsers.add_parser('colorcheck')

    if len(sys.argv) == 1:
        parser.print_help()
        sys.exit(2)

    args = parser.parse_args()

    if args.command == 'format':
        valid_types = ['hex', 'rgb', 'hsl', 'lab', 'name', 'lch', 'hsv', 'oklab']
        if args.type not in valid_types:
            args.color.insert(0, args.type)
            args.type = 'hex'
        colors = get_colors(args.color)
        for c in colors:
            print(format_color(args.type, *c))
    elif args.command == 'mix':
        base = parse_color(args.base_color)
        colors = get_colors(args.color)
        for c in colors:
            if args.colorspace.lower() == 'rgb':
                r = base[0]*(1-args.fraction) + c[0]*args.fraction
                g = base[1]*(1-args.fraction) + c[1]*args.fraction
                b = base[2]*(1-args.fraction) + c[2]*args.fraction
                print(format_color('rgb', r, g, b))
            else:
                mixed = mix_colors(base, c, args.fraction)
                print(format_color('rgb', *mixed))
    elif args.command == 'lighten':
        colors = get_colors(args.color)
        for c in colors:
            h, s, l = rgb_to_hsl(*c)
            l = clamp(l + args.amount)
            print(format_color('hsl', *hsl_to_rgb(h, s, l)))
    elif args.command == 'darken':
        colors = get_colors(args.color)
        for c in colors:
            h, s, l = rgb_to_hsl(*c)
            l = clamp(l - args.amount)
            print(format_color('hsl', *hsl_to_rgb(h, s, l)))
    elif args.command == 'saturate':
        colors = get_colors(args.color)
        for c in colors:
            h, s, l = rgb_to_hsl(*c)
            s = clamp(s + args.amount)
            print(format_color('hsl', *hsl_to_rgb(h, s, l)))
    elif args.command == 'desaturate':
        colors = get_colors(args.color)
        for c in colors:
            h, s, l = rgb_to_hsl(*c)
            s = clamp(s - args.amount)
            print(format_color('hsl', *hsl_to_rgb(h, s, l)))
    elif args.command == 'complement':
        colors = get_colors(args.color)
        for c in colors:
            h, s, l = rgb_to_hsl(*c)
            h = (h + 180) % 360.0
            print(format_color('hsl', *hsl_to_rgb(h, s, l)))
    elif args.command == 'rotate':
        colors = get_colors(args.color)
        for c in colors:
            h, s, l = rgb_to_hsl(*c)
            h = (h + args.degrees) % 360.0
            print(format_color('hsl', *hsl_to_rgb(h, s, l)))
    elif args.command == 'to-gray':
        colors = get_colors(args.color)
        for c in colors:
            x, y, z = rgb_to_xyz(*c)
