            print(format_color('hsl', *clamp_rgb(r, g, b)))
    elif args.command == 'gray':
        r = g = b = clamp(args.lightness)
        print(format_color('rgb', r, g, b))
    elif args.command == 'textcolor':
        colors = get_colors(args.color)
        for c in colors:
            x, y, z = rgb_to_xyz(*c)
            if y > 0.179:
                print(format_color('hex', 0, 0, 0))
            else:
                print(format_color('hex', 1, 1, 1))
    elif args.command == 'distinct':
        for i in range(args.count):
            h = (i * 360.0 / args.count) % 360.0
            print(format_color('hsl', *hsl_to_rgb(h, 1.0, 0.5)))
    elif args.command == 'random':
        for _ in range(args.number):
            h = random.uniform(0, 360)
            print(format_color('hex', *hsl_to_rgb(h, 1.0, 0.5)))
